## Module: RDS

**modules/rds/main.tf**
```hcl
resource "aws_db_subnet_group" "app" {
  name       = "${var.db_name}-subnet-group"
  subnet_ids = var.db_subnet_ids

  tags = merge(var.tags, {
    Name        = "${var.db_name}-subnet-group"
    Environment = var.environment
  })
}

resource "aws_db_instance" "app" {
  identifier     = var.db_name
  engine         = "postgres"
  engine_version = var.postgres_version
  instance_class = var.instance_class

  allocated_storage     = var.allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = var.kms_key_id

  db_name  = var.database_name
  username = var.master_username
  password = var.master_password

  db_subnet_group_name            = aws_db_subnet_group.app.name
  vpc_security_group_ids          = var.security_group_ids
  publicly_accessible             = false
  multi_az                         = var.multi_az
  deletion_protection             = var.deletion_protection
  backup_retention_period         = var.backup_retention_days
  backup_window                   = "03:00-04:00"
  maintenance_window              = "sun:04:00-sun:05:00"
  skip_final_snapshot             = !var.deletion_protection
  final_snapshot_identifier       = var.deletion_protection ? "${var.db_name}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}" : null

  enabled_cloudwatch_logs_exports = ["postgresql"]
  copy_tags_to_snapshot           = true
  auto_minor_version_upgrade      = true

  tags = merge(var.tags, {
    Name        = var.db_name
    Environment = var.environment
  })

  depends_on = [aws_db_subnet_group.app]
}

resource "aws_db_parameter_group" "app" {
  name        = "${var.db_name}-params"
  family      = "postgres${split(".", var.postgres_version)[0]}"
  description = "Parameter group for ${var.db_name}"

  parameter {
    name  = "log_statement"
    value = "all"
  }

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }

  tags = merge(var.tags, {
    Name        = "${var.db_name}-params"
    Environment = var.environment
  })
}
