## Module: IAM

**modules/iam/main.tf**
```hcl
resource "aws_iam_role" "service" {
  name               = "${var.service_name}-role"
  assume_role_policy = jsonencode(var.assume_role_policy)

  tags = merge(var.tags, {
    Name        = "${var.service_name}-role"
    Environment = var.environment
  })
}

resource "aws_iam_role_policy" "s3_access" {
  name   = "${var.service_name}-s3-policy"
  role   = aws_iam_role.service.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          var.s3_bucket_arn,
          "${var.s3_bucket_arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "rds_access" {
  name   = "${var.service_name}-rds-policy"
  role   = aws_iam_role.service.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RDSConnect"
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        Resource = [
          "arn:aws:rds:${var.aws_region}:${var.account_id}:dbuser:${var.db_resource_id}/*"
        ]
      },
      {
        Sid    = "RDSDescribe"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances"
        ]
        Resource = var.db_instance_arn
      }
    ]
  })
}

resource "aws_iam_user" "service" {
  count = var.create_iam_user ? 1 : 0
  name  = "${var.service_name}-user"

  tags = merge(var.tags, {
    Name        = "${var.service_name}-user"
    Environment = var.environment
  })
}

resource "aws_iam_user_policy_attachment" "service" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.service[0].name
  policy_arn = aws_iam_role.service.arn
}

resource "aws_iam_access_key" "service" {
  count = var.create_iam_user ? 1 : 0
  user  = aws_iam_user.service[0].name
}

# OIDC provider for EKS (prod)
resource "aws_iam_openid_connect_provider" "eks" {
  count = var.create_oidc_provider ? 1 : 0

  url             = var.oidc_provider_url
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [var.oidc_thumbprint]

  tags = merge(var.tags, {
    Name        = "${var.service_name}-oidc"
    Environment = var.environment
  })
}

resource "aws_iam_role" "pod_role" {
  count = var.create_oidc_provider ? 1 : 0
  name  = "${var.service_name}-pod-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.eks[0].arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(var.oidc_provider_url, "https://", "")}:sub" = "system:serviceaccount:${var.pod_namespace}:${var.service_name}"
          }
        }
      }
    ]
  })

  tags = merge(var.tags, {
    Name        = "${var.service_name}-pod-role"
    Environment = var.environment
  })
}

resource "aws_iam_role_policy_attachment" "pod_s3" {
  count      = var.create_oidc_provider ? 1 : 0
  role       = aws_iam_role.pod_role[0].name
  policy_arn = aws_iam_role_policy.s3_access.arn
}

resource "aws_iam_role_policy_attachment" "pod_rds" {
  count      = var.create_oidc_provider ? 1 : 0
  role       = aws_iam_role.pod_role[0].name
  policy_arn = aws_iam_role_policy.rds_access.arn
}
