  master_username      = var.db_master_username
  master_password      = var.db_master_password
  environment          = var.environment
}

module "iam" {
  source = "./modules/iam"

  service_name          = var.service_account_name
  environment           = var.environment
  aws_region            = var.aws_region
  account_id            = data.aws_caller_identity.current.account_id
  s3_bucket_arn         = module.s3.bucket_arn
  db_instance_arn       = "arn:aws:rds:${var.aws_region}:${data.aws_caller_identity.current.account_id}:db:${var.db_name}"
  db_resource_id        = module.rds.db_resource_id
  create_iam_user       = var.create_iam_user
  create_oidc_provider  = var.create_oidc_provider
  oidc_provider_url     = var.oidc_provider_url
  oidc_thumbprint       = var.oidc_thumbprint
  pod_namespace         = var.pod_namespace
}
```

**outputs.tf**
```hcl
output "s3_bucket_id" {
  description = "S3 bucket ID"
  value       = module.s3.bucket_id
}

output "s3_bucket_arn" {
  description = "S3 bucket ARN"
  value       = module.s3.bucket_arn
}

output "rds_endpoint" {
  description = "RDS instance endpoint"
  value       = module.rds.db_endpoint
  sensitive   = true
}

output "rds_address" {
  description = "RDS instance address"
  value       = module.rds.db_address
}

output "rds_port" {
  description = "RDS port"
  value       = module.rds.db_port
}

output "iam_role_arn" {
  description = "IAM role ARN"
  value       = module.iam.role_arn
}

output "iam_user_access_key" {
  description = "IAM user access key (dev only)"
  value       = var.create_iam_user ? module.iam.iam_user_access_key_id : null
}

output "pod_role_arn" {
  description = "Pod role ARN (prod only)"
  value       = var.create_oidc_provider ? module.iam.pod_role_arn : null
}

output "environment_info" {
  description = "Environment information"
  value = {
    environment  = var.environment
    region       = var.aws_region
    project_name = var.project_name
  }
}
```

