## Environment Configurations

**dev.tfvars**
```hcl
environment     = "dev"
aws_region      = "us-east-1"
project_name    = "myapp"
app_name        = "webapp"

# S3
s3_bucket_name       = "myapp-dev-assets-${data.aws_caller_identity.current.account_id}"
s3_enable_replication = false
s3_use_kms           = false

# RDS
db_name              = "myapp-dev"
database_name        = "appdb_dev"
db_instance_class    = "db.t3.micro"
db_allocated_storage = 20
db_multi_az          = false
db_backup_retention  = 7

# IAM
service_account_name = "app-service-dev"
create_iam_user      = true
create_oidc_provider = false

# Note: db_subnet_ids, db_security_group_ids, db_master_username, 
# db_master_password should be provided via separate secure tfvars
# or AWS Secrets Manager reference
```

**prod.tfvars**
```hcl
environment     = "prod"
aws_region      = "us-east-1"
replica_region  = "us-west-2"
project_name    = "myapp"
app_name        = "webapp"

# S3
s3_bucket_name       = "myapp-prod-assets-${data.aws_caller_identity.current.account_id}"
s3_enable_replication = true
s3_use_kms           = true

# RDS
db_name              = "myapp-prod"
database_name        = "appdb_prod"
db_instance_class    = "db.t3.medium"
db_allocated_storage = 100
db_multi_az          = true
db_backup_retention  = 30

# IAM (OIDC for EKS)
service_account_name = "app-service-prod"
create_iam_user      = false
create_oidc_provider = true
pod_namespace        = "default"

# oidc_provider_url and oidc_thumbprint must be provided
# (obtain from EKS cluster)
```

